import icontract
from typing import List


@icontract.require(lambda s: len(s) > 1)
@icontract.require(lambda s: any(s[i] != s[j] for i in range(len(s)) for j in range(len(s))))
@icontract.ensure(lambda s, result: result in s)
@icontract.ensure(lambda s, result: any(
    s[j] < result and all(s[k] >= result for k in range(len(s)) if s[k] != s[j]) for j in range(len(s))))
def secondSmallest(s: List[int]) -> int:
    m = s[0]
    for x in s:
        if x < m:
            m = x
    found = False
    r = 0
    for x in s:
        if x != m and (not found or x < r):
            found = True
            r = x
    return r
